HERE=Path(__file__).resolve().parent;PREFIX='external_hilbert_transfer_control'
def esc(v):return html.escape(str(v))
def math(v):return r'\('+esc(v)+r'\)'
def num(v):return math(str(v))
def seconds(v):return math(f'{v:.6f}')
def label(k):return {'delayed-common':'Derived common-point premise','coupled-reverse':'Coupled reversed-line premises'}[k]
def tex(f,m):
    h=f[0]
    if h=='var':return ('x_{'+f[1][1:]+'}') if f[1].startswith('X') else ('v_{'+f[1][1:]+'}' if f[1].startswith('V') else r'\mathrm{'+f[1].replace('_',r'\_')+'}')
    if h=='fun':
        original={v:k for k,v in m['functions'].items()}.get(f[1],f[1]);name=r'\ell' if original=='l' else original if original in ('P','Q','R','m') else r'\operatorname{'+original.replace('_',r'\_')+'}'
        return name+('('+','.join(tex(t,m) for t in f[2])+')' if f[2] else '')
    if h=='pred':
        original={v:k for k,v in m['predicates'].items()}.get(f[1],f[1]);return r'\operatorname{'+original.replace('_',r'\_')+'}'+('('+','.join(tex(t,m) for t in f[2])+')' if f[2] else '')
    if h=='eq':return tex(f[1],m)+'='+tex(f[2],m)
    if h in ('bot','top'):return r'\bot' if h=='bot' else r'\top'
    if h=='not':return r'\neg\bigl('+tex(f[1],m)+r'\bigr)'
    if h in ('and','or','imp'):return r'\bigl('+tex(f[1],m)+{'and':r'\land ','or':r'\lor ','imp':r'\Rightarrow '}[h]+tex(f[2],m)+r'\bigr)'
    if h in ('forall','exists'):return (r'\forall ' if h=='forall' else r'\exists ')+tex(('var',f[1]),m)+r'\;\bigl('+tex(f[2],m)+r'\bigr)'
    raise ValueError('unsupported displayed syntax '+h)
def words(f,m):
    h=f[0]
    if h=='eq':return math(tex(f[1],m))+' equals '+math(tex(f[2],m))
    if h=='not' and f[1][0]=='eq':return math(tex(f[1][1],m))+' differs from '+math(tex(f[1][2],m))
    if h=='pred':
        n={v:k for k,v in m['predicates'].items()}[f[1]];ts=[math(tex(t,m)) for t in f[2]]
        if n in ('Point','Line'):return ts[0]+' is a '+n.lower()
        if n=='Incident':return ts[0]+' is incident with '+ts[1]
        raise ValueError('unsupported original predicate '+n)
    if h=='not':return 'it is false that ('+words(f[1],m)+')'
    if h=='bot':return 'a contradiction'
    if h=='top':return 'a statement that is always true'
    if h in ('forall','exists'):
        vs=[];body=f
        while body[0]==h:vs.append(math(tex(('var',body[1]),m)));body=body[2]
        return ('for every ' if h=='forall' else 'there exist ')+', '.join(vs)+', '+words(body,m)
    if h in ('and','or'):
        def flat(x):return flat(x[1])+flat(x[2]) if x[0]==h else [x]
        parts=['('+words(x,m)+')' for x in flat(f)]
        return ('all of the following hold: ' if h=='and' else 'at least one of the following holds: ')+('; and ' if h=='and' else '; or ').join(parts)
    if h=='imp':return 'if ('+words(f[1],m)+'), then ('+words(f[2],m)+')'
    raise ValueError('unsupported English syntax '+h)
def raw(p):
    b=p.read_bytes();d=dict(sha256=sha(b),bytes=len(b))
    try:d['text']=b.decode('utf-8')
    except UnicodeDecodeError:d['base64']=base64.b64encode(b).decode()
    return d
def panel(o,i,certificate_file):
    path=OUT/('hilbert-'+o['kind']+'.p');m=load(path.with_suffix('.mapping.json'));text=(OUT/(o['stem']+'.tstp')).read_text();rs=records(text);good=o['proof_check']['result'];numbers={r['name']:j+1 for j,r in enumerate(rs)}
    need(not good['introductions'],'this exact reader requires zero introduced symbols')
    parts=['<article class="proof-panel" id="proof-'+str(i)+'"'+(' hidden' if i else '')+'><p><strong>'+label(o['kind'])+'</strong> · run '+num(o['repetition'])+' · '+num(len(rs))+' returned lines. No lemma inputs or introduced witness symbols.</p><p><a href="'+certificate_file+'">Download every complete line certificate</a> · <a href="'+PREFIX+'_'+o['stem']+'.tstp">Exact TSTP output</a>.</p>']
    for j,(r,c) in enumerate(zip(rs,good['checks'])):
        f=closed(r['formula']);kind='input' if c['status']=='checked_input' else 'negation' if c['status']=='checked_negation' else 'consequence'
        parts.append('<div class="proof-line '+kind+'" id="row-'+str(i)+'-'+str(j+1)+'"><span>'+num(j+1)+'</span><div><div class="formula">'+math(tex(f,m))+'</div><p class="translation">'+words(f,m)+'.</p>')
        annotation='Exact supplied formula; the conjecture is the requested target and is never an assumed proof fact.' if kind=='input' else 'Assume the target fails and seek a contradiction.' if kind=='negation' else 'This formula has a complete independently replayed consequence certificate from the actual earlier parents.'
        if c.get('parents'):annotation+=' Parent rows: '+', '.join('<a href="#row-'+str(i)+'-'+str(numbers[n])+'">'+num(numbers[n])+'</a>' for n in c['parents'])+'.'
        parts.append('<p class="annotation">'+annotation+'</p><p><code>'+esc(r['name'])+'</code> · <code>'+esc(c['status'])+'</code> · local certificate SHA-256 <code class="pin">'+sha(json.dumps(c,sort_keys=True,separators=(',',':')))+'</code>.</p>')
        parts.append('<details class="certificate" data-file="'+certificate_file+'" data-index="'+str(j)+'"><summary>Exact annotation and complete local certificate</summary><pre class="certificate-output">Open to load this checked certificate.</pre></details></div></div>')
    return ''.join(parts)+'</article>'
