    compact=dict(status='passed_four_same_assertion_external_proofs',plan_sha256=sha((OUT/'plan.json').read_bytes()),scope=plan['scope'],proof_census=census,corruptions=len(mut['corruptions']),costs=costs,preparation_seconds=plan['preparation_seconds'],producer_seconds=summary['seconds'],audit_seconds=audit['seconds'],mutation_seconds=mut['seconds'],inputs=2,input_entries=[5,5],lemma_inputs=0,unknowns=0,unexecuted=[],observations=[dict(kind=o['kind'],repetition=o['repetition'],lines=o['proof_steps'],e_seconds=o['e_measurement']['wall_seconds'],check_seconds=o['proof_check']['process_wall_seconds'],replay_seconds=o['proof_replay']['process_wall_seconds'],output_sha256=o['output_sha256'],certificate_status=o['certificate_status']) for o in summary['observations']])
