    manifest=dict(status='exported_awaiting_reader_check_and_root_publication',files=[dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,sha256=sha(p.read_bytes())) for p in files],file_count=len(files),proposed_url='https://liuyao12.github.io/geometric-tree-search/docs/research/gcts-rl-renewal/'+PREFIX+'.html?v=20261011-eht1#reader',published_by_child=False,source_scope='Measurement sources frozen before E; report, reproduction and corruption tools separately authored after results.',report_seconds=time.perf_counter()-began)
    dump(OUT/'export.json',manifest);print(dict(files=len(files),html_bytes=(DOC/(PREFIX+'.html')).stat().st_size,evidence_bytes=(DOC/(PREFIX+'_data.json.gz')).stat().st_size,lines=census['lines']),flush=True)
